// This file is generated by AI.

// 从系统文件管理器拖进窗口的文件落点。
//
// ⚠️ 两条都只能走 Tauri 的通道:
//
// 1. **页面收不到 `drop` 事件**。窗口没关 `dragDropEnabled` (见 `tauri.conf.json`), Tauri 在
//    Windows 上接管系统拖放后, 页面的 HTML5 `dragover` / `drop` 不再派发。仓库里曾经有
//    `dataTransfer.files[].path` 那一套取路径的写法, 它在打包后的应用里**一次都没生效过**
//    (而在浏览器里 `File.path` 本来也不存在)。
// 2. **路径只有 webview 的 `onDragDropEvent` 给**。它的坐标是**物理像素**, 必须除以
//    `devicePixelRatio` 才能拿去命中检测 —— 直接当 CSS 像素用, 125% / 150% 缩放下落点会偏移。
//
// 落点由文件树自己登记; 这里只做"订阅事件 -> 换算坐标 -> 找到登记的元素 -> 交回给它"。

import { getCurrentWebview, type DragDropEvent } from '@tauri-apps/api/webview';

/** 落点登记属性: 命中检测靠它从最内层节点向上找已登记的区域 */
const DROP_ATTR = 'data-file-drop';

/**
 * 指针下的元素 (`null` = 当前没有可接收的落点)。
 *
 * 文件树据此高亮"会落进哪一层目录"; 存最内层节点而不是登记的区域元素, 是为了让目录行能被
 * 区分出来 (落在目录行上 = 落进那一层)。
 */
export const externalDrop = $state({
  hit: null as Element | null,
});

/** 落点处理器: 第一个参数是最内层命中节点, 落点据此决定目标目录 */
export type ExternalDropHandler = (hit: Element | null, paths: string[]) => void;

const handlers = new WeakMap<Element, ExternalDropHandler>();

/** 登记一个能接收系统文件的区域。返回注销函数 (组件销毁时必须调用)。 */
export function registerExternalDropZone(element: HTMLElement, handler: ExternalDropHandler): () => void {
  handlers.set(element, handler);
  element.setAttribute(DROP_ATTR, '');
  return () => {
    handlers.delete(element);
    element.removeAttribute(DROP_ATTR);
  };
}

export interface ExternalDropPoint {
  element: HTMLElement;
  hit: Element | null;
  handler: ExternalDropHandler;
}

/** 某个 CSS 像素坐标下的落点。 */
export function externalDropPointAt(x: number, y: number): ExternalDropPoint | null {
  const hit = document.elementFromPoint(x, y);
  if (!(hit instanceof Element)) return null;
  const element = hit.closest<HTMLElement>(`[${DROP_ATTR}]`);
  if (!element) return null;
  const handler = handlers.get(element);
  return handler ? { element, hit, handler } : null;
}

/**
 * 物理像素 -> CSS 像素。
 *
 * `devicePixelRatio` 取不到 (0 / NaN) 时按 1 处理: 高 DPI 下落点会偏, 但总比整条链路抛异常好。
 */
export function toClientPoint(position: { x: number; y: number }, devicePixelRatio: number): { x: number; y: number } {
  const scale = Number.isFinite(devicePixelRatio) && devicePixelRatio > 0 ? devicePixelRatio : 1;
  return { x: position.x / scale, y: position.y / scale };
}

/**
 * 处理一次拖放事件 (单独导出以便调试/测试时手工喂事件)。
 *
 * `enter` / `over` 只更新高亮, `drop` 才真的把路径交给落点, `leave` 清掉高亮。
 */
export function applyExternalDropEvent(payload: DragDropEvent): void {
  if (payload.type === 'leave') {
    externalDrop.hit = null;
    return;
  }

  const point = toClientPoint(payload.position, window.devicePixelRatio);
  const zone = externalDropPointAt(point.x, point.y);

  if (payload.type === 'drop') {
    externalDrop.hit = null;
    zone?.handler(zone.hit, payload.paths);
    return;
  }
  externalDrop.hit = zone?.hit ?? null;
}

/**
 * 订阅 webview 的拖放事件; 返回注销函数。
 *
 * 没有 Tauri (浏览器里跑 `bun run dev`) 时返回一个空操作 —— 这不是错误, 只是没有系统拖放。
 */
export async function startExternalDropWatcher(): Promise<() => void> {
  try {
    const unlisten = await getCurrentWebview().onDragDropEvent((event) => applyExternalDropEvent(event.payload));
    return () => {
      externalDrop.hit = null;
      unlisten();
    };
  } catch (error) {
    if (import.meta.env.DEV) console.debug('[dnd] 系统拖放不可用', error);
    return () => {};
  }
}
